// ACME EMAIL OUTREACH — CONFIG
// Edit values only in this node. Nothing else in this workflow needs changing.
//
// TEST_RUN true         -> nothing reaches a lead. Ships true; see the block below.
// GITHUB_TOKEN blank    -> the run stops at "GitHub configured?" and touches nothing.
// LLM_API_KEY blank     -> the copy is used exactly as built, no AI pass.
// REPORT_WEBHOOK_URL '' -> no run report is posted.

// ---------------------------------------------------------------- Google Sheet
// The lead tracker. Copy the id out of the sheet URL:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
const LEAD_SHEET_ID  = '';
const LEAD_SHEET_TAB = 'Lead Tracker';

// Header names as they appear in row 1. Rename here if the sheet is renamed.
const COLUMNS = {
  row_id:        '#',
  business:      'Business Name',
  type:          'Type',
  website:       'Website / Link',
  task_progress: 'Task Progress',
  dev:           'Dev on task',
  segment:       'Segment / Positioning',
  specialty:     'Specialty Focus',
  email:         'Email',
  priority:      'Priority',
  diagnosis:     'Facelift / CRO Diagnosis',
  pitch_angle:   'Best Pitch Angle',
  status:        'Contact Status',
  method:        'Method of Contact',
  next_action:   'Next Action',
  notes:         'Notes',
  redesign_link: 'Link to the redesign website',
  email_title:   'Email Title',
  email_content: 'Email Content'
};

// ---------------------------------------------------------------- Which rows go out
// A row is emailed when Task Progress matches. Either gate can be left blank to skip
// that column entirely, so you can key off Task Progress, off Status, or off both.
const SEND_WHEN_TASK_PROGRESS = 'Ready for outreach';
const SEND_WHEN_STATUS        = '';   // '' = ignore Contact Status when picking rows
// Both are trimmed and compared case-insensitively.

// The redesign-link column is internal: it points at the deliverables for our own
// reference and never appears in a client's email. Nothing depends on it being filled.
const REQUIRE_REDESIGN_LINK   = false;
const REQUIRE_EMAIL_CHANNEL   = true;   // "Method of Contact" must mention Email
const ONLY_DEV                = '';     // e.g. 'Acme' to send one dev's batch only

// Written back after a successful send. Blank leaves that column alone.
// Contact Status is a dropdown in the sheet, so STATUS_AFTER_SEND must match one of its
// options exactly - same spelling, same capitalisation, no stray space. Anything else
// gets flagged by the sheet's data validation, or rejected outright if it is set to
// "Reject input".
const TASK_PROGRESS_AFTER_SEND = 'Completed';
const STATUS_AFTER_SEND        = 'Contacted';

// Written back when the repo has nothing for that domain. Blank leaves it alone, so
// the row keeps its place in the pipeline and simply gets a note and a next action.
const TASK_PROGRESS_NO_DELIVERABLES = '';
const STATUS_NO_DELIVERABLES        = '';

// ---------------------------------------------------------------- GitHub deliverables
const GITHUB_OWNER   = 'acmetechnology';
const GITHUB_REPO    = 'website-growth-services';
const GITHUB_BRANCH  = 'main';
const GITHUB_PATH    = 'client-deliverables';
// Fine-grained PAT, Contents: Read-only, on this repo. Required — the repo is private.
const GITHUB_TOKEN   = '';

// ---------------------------------------------------------------- Sending
const FROM_EMAIL   = '';
const FROM_NAME    = 'Acme';
const REPLY_TO     = '';
const BCC_EMAIL    = '';          // your own address, so every send is filed
// Contact block, printed at the foot of every email.
const SITE_URL     = 'https://www.acme.example/';
const BOOKING_URL  = 'https://cal.com/technology-acme-5xrlv1/15min';
const WHATSAPP     = '+65 9851 1711';
const SIGNOFF_NAME = 'Operator';
const SIGNOFF_ROLE = 'Acme';
const SUBJECT_TEMPLATE = '{business} — two sample redesigns, attached';

// One safety switch, and the address decides how far a test run goes.
//
//   TEST_RUN true,  TEST_EMAIL blank  -> PREVIEW. Nothing is sent and nothing is
//                                        written. Every lead stops carrying the
//                                        finished subject, html and text to read.
//   TEST_RUN true,  TEST_EMAIL set    -> TEST. The emails really send, but every one
//                                        goes to TEST_EMAIL instead of the lead, with
//                                        the intended recipient named in the subject.
//                                        The sheet is still left alone.
//   TEST_RUN false                    -> LIVE. Real recipients, and the row is
//                                        written back.
//
// Filling in TEST_EMAIL can therefore only ever redirect a send, never cause one:
// going live is always the separate, deliberate act of setting TEST_RUN to false.
const TEST_RUN   = true;
const TEST_EMAIL = '';

// How many leads a TEST run actually mails. A test is for reading the email, not
// for filling your inbox, so this defaults to 1 - the highest-priority eligible row.
// It applies only in test mode; a preview builds the whole batch and a live run
// uses DAILY_CAP.
const TEST_BATCH = 1;

const DAILY_CAP  = 10;    // hard ceiling on sends per execution

// ---------------------------------------------------------------- Attachments
// There is no website to link to, so the designs travel with the email.
//
// Set MAILBOX_LIMIT_MB to the recipient's message limit as their provider states it:
// Gmail and Microsoft 365 are 25 MB, Outlook.com is 20 MB, plenty of corporate gateways
// are 10 MB. It is NOT the file budget - attachments are base64-encoded on the way out,
// which adds about 37%, so a 25 MB mailbox only takes ~18 MB of actual files. The raw
// budget is derived from this, with a little room left for the message body.
//
// PDFs are planned first, so a client whose PDFs fit but whose PDFs plus previews do
// not still gets the PDFs. Measured over the 43 client folders at a 25 MB limit:
// 31 get the PDFs (22 with previews too), and the other 12 have PDF sets of 17-45 MB
// that no mailbox will accept.
const MAILBOX_LIMIT_MB = 25;
const ATTACH_PDFS      = true;    // print-quality, the real deliverable
const ATTACH_PNGS      = true;    // full-page previews, added if there is room left

// ---------------------------------------------------------------- Optional AI polish
// Rewrites the subject line and opening paragraph only. Every fact, link and tip
// in the email is built in code and is never handed to the model.
const LLM_BASE_URL = 'https://llm.acme.example';
const LLM_API_KEY  = '';
const LLM_MODEL    = 'modelark/seed-2-0-pro-260328';

// ---------------------------------------------------------------- Optional report
const REPORT_WEBHOOK_URL = '';

const MODE = TEST_RUN !== true ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

return [{
  json: {
    lead_sheet_id:  LEAD_SHEET_ID,
    lead_sheet_tab: LEAD_SHEET_TAB,
    columns:        COLUMNS,

    send_when_task_progress: SEND_WHEN_TASK_PROGRESS.trim(),
    send_when_status:        SEND_WHEN_STATUS.trim(),
    require_redesign_link:   REQUIRE_REDESIGN_LINK,
    require_email_channel:   REQUIRE_EMAIL_CHANNEL,
    only_dev:                ONLY_DEV.trim(),

    task_progress_after_send:      TASK_PROGRESS_AFTER_SEND.trim(),
    status_after_send:             STATUS_AFTER_SEND.trim(),
    task_progress_no_deliverables: TASK_PROGRESS_NO_DELIVERABLES.trim(),
    status_no_deliverables:        STATUS_NO_DELIVERABLES.trim(),

    github_owner:  GITHUB_OWNER,
    github_repo:   GITHUB_REPO,
    github_branch: GITHUB_BRANCH,
    github_path:   GITHUB_PATH.replace(/^\/+|\/+$/g, ''),
    github_auth:   'Bearer ' + GITHUB_TOKEN.trim(),

    from_email:       FROM_EMAIL.trim(),
    from_name:        FROM_NAME,
    from_header:      FROM_NAME ? FROM_NAME + ' <' + FROM_EMAIL.trim() + '>' : FROM_EMAIL.trim(),
    reply_to:         REPLY_TO.trim(),
    bcc_email:        BCC_EMAIL.trim(),
    site_url:         SITE_URL,
    booking_url:      BOOKING_URL,
    whatsapp:         WHATSAPP.trim(),
    whatsapp_link:    'https://wa.me/' + WHATSAPP.replace(/[^0-9]/g, ''),
    signoff_name:     SIGNOFF_NAME,
    signoff_role:     SIGNOFF_ROLE,
    subject_template: SUBJECT_TEMPLATE,

    daily_cap:  Number(DAILY_CAP) || 0,
    attach_pngs:      ATTACH_PNGS === true,
    attach_pdfs:      ATTACH_PDFS === true,
    mailbox_limit_mb: Number(MAILBOX_LIMIT_MB) || 0,
    // raw bytes: strip the ~37% base64 inflation and reserve 256 KB for the message itself
    attach_budget: Math.max(0,
      Math.floor(((Number(MAILBOX_LIMIT_MB) || 0) * 1048576 - 262144) / 1.37)),
    test_email: TEST_EMAIL.trim(),
    test_batch: Number(TEST_BATCH) || 1,

    llm_base_url: LLM_BASE_URL.replace(/\/+$/, ''),
    llm_api_key:  LLM_API_KEY.trim(),
    llm_model:    LLM_MODEL,

    report_webhook_url: REPORT_WEBHOOK_URL.trim(),

    // derived flags - gates read these, never the raw constants
    github_enabled: GITHUB_TOKEN.trim() !== '',
    llm_enabled:    LLM_API_KEY.trim() !== '',
    report_enabled: REPORT_WEBHOOK_URL.trim() !== '',

    mode:         MODE,               // 'preview' | 'test' | 'live'
    preview_only: MODE === 'preview', // built, shown, never sent
    test_send:    MODE === 'test',    // sent, but redirected to TEST_EMAIL
    live_send:    MODE === 'live',    // the only mode that writes to the sheet
    send_enabled: MODE !== 'preview'
  }
}];

// Decide who gets an email this run, and stop there.
// Every reason a row is skipped is counted, because "0 sent" with no explanation is
// the single most common support question this workflow will generate.
const cfg = $('config').first().json;
const C = cfg.columns;

const rows = $input.all().map((i) => i.json);

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const PLACEHOLDER = new Set(['', 'tbd', 'n/a', 'na', 'none', '-', 'unknown', 'pending']);

const val = (row, key) => String(row[C[key]] ?? '').trim();
// Status and Task Progress are typed by hand into the sheet, so compare loosely.
const same = (a, b) => a.toLowerCase() === String(b || '').trim().toLowerCase();

const domainOf = (url) => String(url || '')
  .trim()
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split(/[/?#]/)[0]
  .replace(/\.$/, '');

// "David Ho (Insurance Broker)" -> a person. "Acclaim Insurance Brokers" -> a firm.
// Wrong guesses here are visible to the client, so the test is deliberately strict.
const FIRM_WORDS = /\b(law|llc|llp|lp|pte|ltd|limited|corporation|corp|chambers|associates|partners|advisory|advisers|advisors|capital|management|financial|insurance|brokers?|group|holdings|consultancy|services|company|co|firm|practice|wealth|asset|trust|planners?|solutions)\b/i;

const greetingFor = (business) => {
  const cleaned = String(business || '')
    .replace(/\([^)]*\)/g, ' ')           // drop "(Insurance Broker)"
    .replace(/,\s*(cfp|cfa|afc|chfc|clu|mba|llb|jd|phd|esq)\.?\b/gi, ' ')
    .replace(/[&]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const parts = cleaned.split(' ').filter(Boolean);
  if (parts.length === 2 && !FIRM_WORDS.test(cleaned) && parts.every((p) => /^[A-Z][a-z'-]+$/.test(p))) {
    return { greeting: 'Hi ' + parts[0] + ',', person: cleaned };
  }
  return { greeting: 'Hi there,', person: '' };
};

const PRIORITY_RANK = { high: 0, medium: 1, low: 2 };

const skipped = {
  wrong_task_progress: 0,
  wrong_status: 0,
  no_valid_email: 0,
  no_redesign_link: 0,
  not_an_email_channel: 0,
  other_dev: 0,
  duplicate_email: 0,
  over_cap: 0
};

const seenEmail = new Set();
const candidates = [];

for (let i = 0; i < rows.length; i++) {
  const row = rows[i];
  const sourceRow = i + 2;                 // header is row 1

  // A blank gate in config means "do not look at that column at all".
  if (cfg.send_when_task_progress && !same(val(row, 'task_progress'), cfg.send_when_task_progress)) {
    skipped.wrong_task_progress++; continue;
  }
  if (cfg.send_when_status && !same(val(row, 'status'), cfg.send_when_status)) {
    skipped.wrong_status++; continue;
  }
  if (cfg.only_dev && val(row, 'dev') !== cfg.only_dev) { skipped.other_dev++; continue; }

  const email = val(row, 'email').toLowerCase();
  if (PLACEHOLDER.has(email) || !EMAIL_RE.test(email)) { skipped.no_valid_email++; continue; }

  // A generated email is built around this link, so without one there is nothing to
  // send. A row carrying its own Email Content is exempt: whoever wrote it decided
  // what it points at.
  const redesignLink = val(row, 'redesign_link');
  const hasOwnCopy = val(row, 'email_content').length > 40;
  const linkLooksReal = !PLACEHOLDER.has(redesignLink.toLowerCase()) &&
                        /^https?:\/\//i.test(redesignLink);
  if (cfg.require_redesign_link && !linkLooksReal && !hasOwnCopy) {
    skipped.no_redesign_link++; continue;
  }

  if (cfg.require_email_channel && !/email/i.test(val(row, 'method'))) { skipped.not_an_email_channel++; continue; }

  if (seenEmail.has(email)) { skipped.duplicate_email++; continue; }
  seenEmail.add(email);

  const business = val(row, 'business');
  const who = greetingFor(business);

  candidates.push({
    row_id:          val(row, 'row_id'),
    _source_row:     sourceRow,
    business,
    business_display: business.replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim() || business,
    greeting:        who.greeting,
    contact_person:  who.person,
    email,
    website:         val(row, 'website'),
    domain:          domainOf(val(row, 'website')),
    type:            val(row, 'type'),
    segment:         val(row, 'segment'),
    specialty:       val(row, 'specialty'),
    priority:        val(row, 'priority'),
    task_progress:   val(row, 'task_progress'),
    status:          val(row, 'status'),
    diagnosis:       val(row, 'diagnosis'),
    pitch_angle:     val(row, 'pitch_angle'),
    redesign_link:   redesignLink,
    existing_notes:  val(row, 'notes'),
    existing_title:  val(row, 'email_title'),
    existing_body:   val(row, 'email_content'),
    // Copy already written into the sheet by a human wins over anything we build.
    _has_custom_subject: val(row, 'email_title') !== '',
    _has_custom_body:    val(row, 'email_content').length > 40,
    _priority_rank:  PRIORITY_RANK[val(row, 'priority').toLowerCase()] ?? 3
  });
}

candidates.sort((a, b) =>
  (a._priority_rank - b._priority_rank) || (Number(a.row_id) - Number(b.row_id))
);

// A test run mails TEST_BATCH leads (1 by default) - enough to read the email, not
// enough to fill an inbox. A preview builds the whole batch because it sends nothing.
const testing = cfg.test_send === true;
const cap = testing
  ? (cfg.test_batch > 0 ? cfg.test_batch : 1)
  : (cfg.daily_cap > 0 ? cfg.daily_cap : candidates.length);

skipped.over_cap = Math.max(0, candidates.length - cap);
const selected = candidates.slice(0, cap);

const summary = {
  rows_read: rows.length,
  eligible: candidates.length,
  selected: selected.length,
  cap,
  cap_reason: testing ? 'TEST_BATCH, because this is a test run' : 'DAILY_CAP',
  skipped
};

if (!selected.length) {
  return [{ json: { _nothing_to_send: true, _summary: summary } }];
}

return selected.map((lead) => ({ json: Object.assign({ _summary: summary }, lead) }));

// Turn a GitHub directory listing into the exact URLs this email needs.
// A missing folder is normal, not an error: not every redesigned row has been
// pushed to this branch yet. It routes to "STOP: no deliverables in repo".
const cfg = $('config').first().json;
const lead = $('Loop over leads').first().json;

const api = 'https://api.github.com/repos/' + cfg.github_owner + '/' + cfg.github_repo + '/contents/';
const rawUrl = (path) => api + path.split('/').map(encodeURIComponent).join('/') + '?ref=' + encodeURIComponent(cfg.github_branch);

// The HTTP node splits a JSON array into items; a 404 body arrives as one item
// with a `message`. Both shapes land here, so normalise before reading.
const files = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j)) { files.push(...j); continue; }
  if (Array.isArray(j.data)) { files.push(...j.data); continue; }
  if (j.name && j.path) files.push(j);
}

const flat = files.filter((f) => f && f.type === 'file' && typeof f.name === 'string');
const named = (n) => flat.find((f) => f.name.toLowerCase() === n);

const notes = named('facelift-cro-and-pitch-notes.txt');
const seo   = named('seo-geo-tip.txt');

// "establishment-modern.pdf" -> "establishment-modern". The PDF is the canonical
// per-direction artefact; the .desktop/.mobile PNGs are previews of the same thing.
const directions = flat
  .filter((f) => /\.pdf$/i.test(f.name))
  .map((f) => f.name.replace(/\.pdf$/i, ''))
  .filter((d) => !/^(facelift|seo)/i.test(d))
  .sort();

const previews = {};
for (const d of directions) {
  const desktop = named(d.toLowerCase() + '.desktop.png');
  const pdf = named(d.toLowerCase() + '.pdf');
  previews[d] = {
    desktop_png:       desktop ? rawUrl(desktop.path) : '',
    desktop_png_name:  desktop ? desktop.name : '',
    desktop_png_bytes: desktop ? Number(desktop.size || 0) : 0,
    pdf:               pdf ? rawUrl(pdf.path) : '',
    pdf_name:          pdf ? pdf.name : '',
    pdf_bytes:         pdf ? Number(pdf.size || 0) : 0
  };
}

const hasDeliverables = Boolean(notes) && directions.length > 0;

return [{
  json: Object.assign({}, lead, {
    _has_deliverables: hasDeliverables,
    _deliverable_path: cfg.github_path + '/' + lead.domain,
    _file_count: flat.length,
    notes_url: notes ? rawUrl(notes.path) : '',
    seo_url:   seo ? rawUrl(seo.path) : '',
    directions,
    previews,
    _skip_reason: hasDeliverables
      ? ''
      : (flat.length === 0
          ? 'no folder for ' + lead.domain + ' on branch ' + cfg.github_branch
          : 'folder exists but has no pitch notes or no design directions')
  })
}];

// Build the email from the two .txt files in the client's deliverable folder.
// Everything here is extraction and formatting — no facts are invented. If a section
// cannot be parsed it is dropped, never guessed at, because this goes to a stranger.
const cfg  = $('config').first().json;
const base = $('pick deliverable files').first().json;

const readText = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    const raw = typeof j.data === 'string' ? j.data : (typeof j === 'string' ? j : '');
    return raw.replace(/\r\n/g, '\n');
  } catch (e) {
    return '';
  }
};

const notesRaw = readText('[cred] GitHub - get pitch notes');
const seoRaw   = readText('[cred] GitHub - get seo geo tip');

// ---------------------------------------------------------------- small helpers
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const tidy = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// These files quote page titles and headings, so a naive split on "." lands inside
// a quotation and hands the client half a sentence. Track quote and paren depth.
const splitSentences = (s) => {
  const out = [];
  let buf = '', paren = 0, quoted = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    buf += c;
    if (c === '(') paren++;
    else if (c === ')') paren = Math.max(0, paren - 1);
    else if (c === '"') quoted = !quoted;
    else if (c === '\u201C') quoted = true;
    else if (c === '\u201D') quoted = false;
    else if (c === '.' || c === '!' || c === '?') {
      let j = i + 1;
      while (j < s.length && '")\u201D'.indexOf(s[j]) !== -1) {   // closer belongs to this sentence
        if (s[j] === ')') paren = Math.max(0, paren - 1); else quoted = false;
        buf += s[j];
        j++;
      }
      i = j - 1;
      // A '?' inside a quoted page heading is not the end of the sentence, so only
      // break when what follows actually starts a new one.
      const rest = s.slice(j).replace(/^\s+/, '');
      if (paren === 0 && !quoted && (rest === '' || /^[A-Z\u201C"(]/.test(rest))) {
        out.push(buf.trim());
        buf = '';
      }
    }
  }
  if (buf.trim()) out.push(buf.trim());
  return out;
};

// Whole sentences up to a budget. Drops the second sentence rather than cutting it,
// and only ever ellipsis-truncates when a single sentence is longer than the budget.
const firstSentences = (s, n, maxChars) => {
  const clean = tidy(s);
  if (!clean) return '';
  const parts = splitSentences(clean);
  let out = '';
  for (const part of parts.slice(0, n)) {
    const next = out ? out + ' ' + part : part;
    if (out && maxChars && next.length > maxChars) break;
    out = next;
  }
  if (!out) out = parts[0] || clean;
  if (maxChars && out.length > maxChars) {
    out = out.slice(0, maxChars).replace(/[\s,;:.\u2014-]+\S*$/, '') + '\u2026';
  }
  return out;
};

// Plain-text bodies go out at a readable width; long unwrapped lines look broken
// in a lot of mail clients.
const wrap = (s, width) => {
  const cols = width || 78;
  const out = [];
  for (const para of String(s ?? '').split('\n')) {
    if (!para.trim()) { out.push(''); continue; }
    const m = para.match(/^(\s*)((?:\d+\.|[*-])\s+)?/);
    const indent = m[1] || '';
    const hang = indent + ' '.repeat((m[2] || '').length);   // list items get a hanging indent
    const words = para.trim().split(/\s+/);
    let line = indent + words[0];
    for (let i = 1; i < words.length; i++) {
      if ((line + ' ' + words[i]).length > cols) { out.push(line); line = hang + words[i]; }
      else line += ' ' + words[i];
    }
    out.push(line);
  }
  return out.join('\n');
};

const titleCase = (slug) => String(slug || '')
  .split(/[-_]/).filter(Boolean)
  .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
  .join(' ');

const unquote = (s) => tidy(s).replace(/^["“”']+|["“”']+$/g, '');

// ---------------------------------------------------------------- pitch notes
// Labels in these files carry slashes and brackets, so match a plain line prefix
// instead of escaping them into a pattern.
const afterLabel = (text, label) => {
  const needle = (label + ':').toLowerCase();
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (t.toLowerCase().startsWith(needle)) return tidy(t.slice(needle.length));
  }
  return '';
};

// A heading in these files is a line in ALL CAPS on its own.
const sectionBody = (text, headingRe) => {
  const lines = text.split('\n');
  const start = lines.findIndex((l) => headingRe.test(l.trim()));
  if (start === -1) return '';
  const body = [];
  for (let i = start + 1; i < lines.length; i++) {
    const t = lines[i].trim();
    if (t && t === t.toUpperCase() && /[A-Z]{4}/.test(t) && !/^\d/.test(t)) break;
    body.push(lines[i]);
  }
  return body.join('\n').trim();
};

const diagnosis  = unquote(afterLabel(notesRaw, 'Facelift / CRO Diagnosis (CSV column)')) || unquote(base.diagnosis);
const pitchAngle = unquote(afterLabel(notesRaw, 'Best Pitch Angle (CSV column)')) || unquote(base.pitch_angle);

const declaredDirections = afterLabel(notesRaw, 'Design directions delivered')
  .split(',').map((s) => tidy(s)).filter(Boolean);

const directions = (declaredDirections.length ? declaredDirections : base.directions) || [];

// Inside "THE TWO DIRECTIONS", each paragraph opens "<slug>: <description>".
const directionsSection = sectionBody(notesRaw, /^THE (TWO )?DIRECTIONS/i);
const describeDirection = (slug) => {
  const needle = (slug + ':').toLowerCase();
  for (const para of directionsSection.split(/\n\s*\n/)) {
    const t = tidy(para);
    if (t.toLowerCase().startsWith(needle)) return firstSentences(t.slice(needle.length), 2, 300);
  }
  return '';
};

const directionCards = directions
  .map((slug) => ({
    slug,
    name: titleCase(slug),
    blurb: describeDirection(slug),
    preview: (base.previews && base.previews[slug]) || {}
  }))
  .filter((d) => d.name);

const whyParagraph =
  firstSentences(sectionBody(notesRaw, /^HOW THE PITCH ANGLE IS EXECUTED/i), 2, 320) ||
  firstSentences(sectionBody(notesRaw, /^HOW THE DIAGNOSIS IS ADDRESSED/i), 2, 320);

// ---------------------------------------------------------------- SEO / GEO scan
const parseTips = (block) => {
  const out = [];
  let current = null;
  for (const line of block.split('\n')) {
    const m = line.match(/^\s*\d+\.\s+(.*)$/);
    if (m) {
      if (current) out.push(current);
      current = { headline: tidy(m[1]).replace(/\.$/, ''), body: [] };
    } else if (current && line.trim()) {
      current.body.push(line.trim());
    } else if (current && !line.trim() && current.body.length) {
      // blank line inside an item is fine; a numbered line ends it
    }
  }
  if (current) out.push(current);
  return out.map((t) => ({ headline: t.headline, body: firstSentences(t.body.join(' '), 2, 320) }))
            .filter((t) => t.headline);
};

const sliceBetween = (text, startRe, endRe) => {
  const lines = text.split('\n');
  const s = lines.findIndex((l) => startRe.test(l.trim()));
  if (s === -1) return '';
  let e = lines.length;
  for (let i = s + 1; i < lines.length; i++) {
    if (endRe.test(lines[i].trim())) { e = i; break; }
  }
  return lines.slice(s + 1, e).join('\n');
};

const seoTips = parseTips(sliceBetween(seoRaw, /^SEO\b/i, /^GEO\b/i)).slice(0, 2);
const geoTips = parseTips(sliceBetween(seoRaw, /^GEO\b/i, /^(These are the quick wins|A full SEO)/i)).slice(0, 2);

// ---------------------------------------------------------------- copy
const business = base.business_display || base.business;
// The sheet's Email Title / Email Content win over anything we build. A human who
// wrote copy into those cells meant it, and this workflow must not overwrite them.
// There is no live site and no client-facing link. The designs travel as attachments,
// so the copy points at the attachments and at how to reach us, nothing else.
// Plan the attachments here, because the copy has to describe what is actually going
// to be in the email. PNGs first - measured across the 43 client folders they are 2.3 MB
// median and 4.6 MB at worst, so they always fit - then PDFs while the budget allows.
// The budget is on the raw bytes; base64 adds about 37% on the wire.
const previews = base.previews || {};

// Each format is all-or-nothing. Sending a preview of both directions but a PDF of
// only one reads as carelessness, so a group that does not fit whole is left out whole.
const groupFor = (key, nameKey, bytesKey) => (base.directions || [])
  .map((d) => previews[d] || {})
  .filter((pv) => pv[key] && pv[nameKey])
  .map((pv) => ({ url: pv[key], filename: pv[nameKey], bytes: Number(pv[bytesKey]) || 0 }));

const attachments = [];
let attachBytes = 0;

const planGroup = (group, wanted) => {
  if (!wanted || !group.length) return false;
  if (group.length !== (base.directions || []).length) return false;   // incomplete set
  const size = group.reduce((n, f) => n + f.bytes, 0);
  if (attachBytes + size > cfg.attach_budget) return false;
  for (const f of group) {
    attachments.push({ url: f.url, filename: f.filename, bytes: f.bytes,
                       prop: 'attachment_' + attachments.length });
  }
  attachBytes += size;
  return true;
};

// PDFs first - they are the actual deliverable, and claiming the budget for them means
// a client whose PDFs fit but whose PDFs plus previews do not still gets the PDFs.
// The previews then take whatever is left; they are 2.3 MB median, 4.6 MB at worst.
const pdfsAttached = planGroup(groupFor('pdf', 'pdf_name', 'pdf_bytes'), cfg.attach_pdfs);
const pngsAttached = planGroup(
  groupFor('desktop_png', 'desktop_png_name', 'desktop_png_bytes'), cfg.attach_pngs);

const attachNames = attachments.map((a) => a.filename);

const whatsYouGot =
  pdfsAttached && pngsAttached
    ? 'Attached: the print-quality PDF of each direction, plus a full-page preview.'
  : pdfsAttached
    ? 'Attached: the print-quality PDF of each direction.'
  : pngsAttached
    ? 'Attached: a full-page preview of each direction. The print-quality PDFs are too '
      + 'large to email - say the word and we will get them to you.'
    : 'Both directions are described below. The files are too large to email - say the '
      + 'word and we will get them to you.';

const nextSteps = 'Nothing to sign and nothing owed - these are sample redesigns, built '
  + 'from your public site on our own time, not a commissioned job. If one of the two '
  + 'directions is close, tell us which and we will take it from there. And the two scans '
  + 'above are a few minutes of what a full SEO and GEO review covers, so if you want the '
  + 'whole picture of where the site stands, just ask.';

const builtSubject = tidy(cfg.subject_template.replace('{business}', business)).slice(0, 120);
const subject = base._has_custom_subject ? tidy(base.existing_title).slice(0, 200) : builtSubject;

const intro = diagnosis
  ? 'We redesigned ' + base.domain + ' as a sample - unasked, on our own time, to show what '
    + 'it could look like. What stood out on the current site: ' + diagnosis.replace(/\.$/, '')
    + '. Both directions set out to fix that.'
  : 'We redesigned ' + base.domain + ' as a sample - unasked, on our own time, to show what '
    + 'it could look like. Two directions, both below.';

// ---------------------------------------------------------------- HTML
const INK = '#16181d', MUTED = '#5b6472', LINE = '#e3e6ea', ACCENT = '#0b5fff', BG = '#f5f6f8';
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

const p = (html, extra) =>
  '<p style="margin:0 0 16px;font:400 15px/1.6 ' + FONT + ';color:' + INK + ';' + (extra || '') + '">' + html + '</p>';

const h = (text) =>
  '<p style="margin:28px 0 12px;font:600 12px/1.4 ' + FONT + ';letter-spacing:.08em;text-transform:uppercase;color:' + MUTED + '">' + esc(text) + '</p>';

const rule = '<div style="height:1px;background:' + LINE + ';margin:24px 0"></div>';

const button = (href, label) =>
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 8px"><tr><td bgcolor="' + ACCENT + '" style="border-radius:6px">' +
  '<a href="' + esc(href) + '" style="display:inline-block;padding:13px 26px;font:600 15px/1 ' + FONT + ';color:#ffffff;text-decoration:none;border-radius:6px">' + esc(label) + '</a>' +
  '</td></tr></table>';

const card = (inner) =>
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:0 0 12px;border:1px solid ' + LINE + ';border-radius:8px"><tr><td style="padding:16px 18px">' + inner + '</td></tr></table>';

const directionsHtml = directionCards.map((d) => card(
  '<p style="margin:0 0 6px;font:600 15px/1.4 ' + FONT + ';color:' + INK + '">' + esc(d.name) + '</p>' +
  (d.blurb ? '<p style="margin:0;font:400 14px/1.6 ' + FONT + ';color:' + MUTED + '">' + esc(d.blurb) + '</p>' : '')
)).join('');

const tipsHtml = (tips) => tips.map((t) =>
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:0 0 14px"><tr>' +
  '<td width="16" valign="top" style="font:600 15px/1.6 ' + FONT + ';color:' + ACCENT + '">&bull;</td>' +
  '<td valign="top">' +
  '<p style="margin:0 0 4px;font:600 14px/1.5 ' + FONT + ';color:' + INK + '">' + esc(t.headline) + '</p>' +
  (t.body ? '<p style="margin:0;font:400 14px/1.6 ' + FONT + ';color:' + MUTED + '">' + esc(t.body) + '</p>' : '') +
  '</td></tr></table>'
).join('');

const contactRow = (label, href, text) =>
  '<tr><td style="padding:2px 0;font:400 14px/1.7 ' + FONT + ';color:' + MUTED + '">' +
  '<span style="display:inline-block;min-width:88px;color:' + MUTED + '">' + esc(label) + '</span>' +
  '<a href="' + esc(href) + '" style="color:' + ACCENT + ';text-decoration:none">' + esc(text) + '</a>' +
  '</td></tr>';

const contactBlock =
  h('Reach us') +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0">' +
  contactRow('WhatsApp', cfg.whatsapp_link, cfg.whatsapp) +
  contactRow('Book a call', cfg.booking_url, '15 minutes, pick a slot') +
  contactRow('Website', cfg.site_url, cfg.site_url.replace(/^https?:\/\//, '').replace(/\/$/, '')) +
  '</table>';

const preheader = 'Two sample redesigns of ' + base.domain + ', plus a quick SEO and AI-answer scan.';

const body =
  '<p style="margin:0 0 24px;font:700 16px/1 ' + FONT + ';letter-spacing:.02em;color:' + INK + '">Acme<span style="font-weight:400;color:' + MUTED + '"> &middot; website growth</span></p>' +
  p(esc(base.greeting)) +
  p(esc(intro)) +
  p(esc(whatsYouGot), 'color:' + MUTED) +
  rule +
  h('The two directions') +
  directionsHtml +
  (whyParagraph ? p(esc(whyParagraph), 'color:' + MUTED) : '') +
  (seoTips.length ? h('Two SEO fixes we noticed') + tipsHtml(seoTips) : '') +
  (geoTips.length ? h('Two AI-answer (GEO) fixes') + tipsHtml(geoTips) : '') +
  rule +
  h('What happens next') +
  p(esc(nextSteps)) +
  button(cfg.booking_url, 'Book 15 minutes') +
  p('If neither direction is right, replying &quot;not for us&quot; is a perfectly good answer and we will not follow up.', 'color:' + MUTED + ';font-size:13px') +
  contactBlock;

const footer =
  '<div style="height:1px;background:' + LINE + ';margin:8px 0 18px"></div>' +
  '<p style="margin:0;font:400 14px/1.6 ' + FONT + ';color:' + INK + '">' + esc(cfg.signoff_name) + '<br>' +
  '<span style="color:' + MUTED + '">' + esc(cfg.signoff_role) + '</span></p>';

const shell = (inner) =>
  '<div style="display:none;max-height:0;overflow:hidden;opacity:0">' + esc(preheader) + '</div>' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:' + BG + ';margin:0;padding:24px 12px"><tr><td align="center">' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background:#ffffff;border:1px solid ' + LINE + ';border-radius:10px">' +
  '<tr><td style="padding:28px 32px 8px">' + inner + '</td></tr>' +
  '<tr><td style="padding:0 32px 28px">' + footer + '</td></tr>' +
  '</table></td></tr></table>';

const html = shell(body);

// ---------------------------------------------------------------- plain text
const textParts = [
  base.greeting, '',
  intro, '',
  whatsYouGot, '',
  'THE TWO DIRECTIONS', ''
];
for (const d of directionCards) {
  textParts.push('* ' + d.name + (d.blurb ? ' - ' + d.blurb : ''));
}
textParts.push('');
if (whyParagraph) textParts.push(whyParagraph, '');
if (seoTips.length) {
  textParts.push('TWO SEO FIXES WE NOTICED', '');
  seoTips.forEach((t, i) => textParts.push((i + 1) + '. ' + t.headline, t.body ? '   ' + t.body : '', ''));
}
if (geoTips.length) {
  textParts.push('TWO AI-ANSWER (GEO) FIXES', '');
  geoTips.forEach((t, i) => textParts.push((i + 1) + '. ' + t.headline, t.body ? '   ' + t.body : '', ''));
}
textParts.push(
  'WHAT HAPPENS NEXT', '',
  nextSteps, '',
  'If neither direction is right, replying "not for us" is a perfectly good answer and '
    + 'we will not follow up.', '',
  'REACH US', '',
  'WhatsApp: ' + cfg.whatsapp,
  'Book a call: ' + cfg.booking_url,
  'Website: ' + cfg.site_url, '',
  cfg.signoff_name,
  cfg.signoff_role
);
const text = wrap(textParts.join('\n'), 78)
  .replace(/(?:\r?\n){3,}/g, '\n\n');

// ---------------------------------------------------------------- sheet-authored copy
// If someone typed a body into the sheet's Email Content cell, that is the email.
// It goes out in the same wrapper so it still looks like everything else we send,
// but not one word of it is rewritten.
const wordmark = '<p style="margin:0 0 24px;font:700 16px/1 ' + FONT +
  ';letter-spacing:.02em;color:' + INK + '">Acme<span style="font-weight:400;color:' +
  MUTED + '"> &middot; website growth</span></p>';

const linkify = (t) => esc(t).replace(
  /(https?:\/\/[^\s<]+)/g,
  '<a href="$1" style="color:' + ACCENT + '">$1</a>');

const customBody = base._has_custom_body ? String(base.existing_body).replace(/\r\n/g, '\n') : '';

const customHtml = customBody
  ? shell(wordmark + customBody.split(/\n\s*\n/)
      .filter((para) => para.trim())
      .map((para) => p(linkify(para.trim()).replace(/\n/g, '<br>')))
      .join(''))
  : '';

const copySource = customBody
  ? (base._has_custom_subject ? 'sheet' : 'sheet-body')
  : (base._has_custom_subject ? 'sheet-subject' : 'built');

return [{
  json: Object.assign({}, base, {
    subject,
    intro,
    html: customHtml || html,
    text: customBody ? wrap(customBody, 78) : text,
    // 'built' is the only source the AI polish step is allowed to touch.
    _copy_source: copySource,
    _attachment_names: attachNames,
    _attachments: attachments,
    _attachment_bytes: attachBytes,
    _parsed: {
      diagnosis,
      pitch_angle: pitchAngle,
      directions: directionCards.map((d) => d.name),
      seo_tips: seoTips.length,
      geo_tips: geoTips.length,
      notes_bytes: notesRaw.length,
      seo_bytes: seoRaw.length
    }
  })
}];

// The row is marked redesigned but the branch has nothing for this domain.
// Not an error: it means the work has not been pushed yet. Flag it for the dev.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _outcome: 'no_deliverables' })
}));

// Take the model's subject + opening paragraph, or keep ours.
// The model never sees or writes a link, a tip or a direction name, so a bad
// response can only ever cost us the intro, never a fact.
const built = $('build email content').first().json;

let polished = {};
try {
  const raw = $input.first().json;
  const content = raw?.choices?.[0]?.message?.content ?? '';
  const stripped = String(content).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  polished = stripped ? JSON.parse(stripped) : {};
} catch (e) {
  polished = {};
}

const subject = typeof polished.subject === 'string' && polished.subject.trim().length > 8
  ? polished.subject.trim().slice(0, 120)
  : built.subject;

const intro = typeof polished.intro === 'string' && polished.intro.trim().length > 40
  ? polished.intro.trim()
  : built.intro;

const used = subject !== built.subject || intro !== built.intro;

// Swap the intro inside both bodies rather than rebuilding them.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const html = built.html.split(esc(built.intro)).join(esc(intro));
const text = built.text.split(built.intro).join(intro);

return [{ json: Object.assign({}, built, { subject, intro, html, text, _llm_applied: used }) }];

// One item per file to download. The plan was made in "build email content" so the
// copy and the attachments can never disagree about what is in the email.
const email = $input.first().json;
return (email._attachments || []).map((a) => ({ json: a }));

// Fold the downloaded files back onto the single email item as binary properties.
// n8n's email node takes a comma-separated list of those property names.
const email = $('any attachments?').first().json;
const plan = email._attachments || [];

const binary = {};
const attached = [];
const failed = [];

$input.all().forEach((item, i) => {
  const source = item.binary || {};
  const data = source.data || Object.values(source)[0];
  const planned = plan[i] || {};
  if (!data) {
    failed.push(planned.filename || ('file ' + i));
    return;
  }
  const prop = 'attachment_' + attached.length;
  // Name it after the file in the repo, not after whatever the URL happened to end in.
  binary[prop] = Object.assign({}, data, {
    fileName: planned.filename || data.fileName,
    mimeType: data.mimeType || (/\.pdf$/i.test(planned.filename || '') ? 'application/pdf' : 'image/png')
  });
  attached.push(planned.filename || prop);
});

return [{
  json: Object.assign({}, email, {
    _attachment_props: Object.keys(binary).join(','),
    _attached: attached,
    _attachments_failed: failed
  }),
  binary
}];

// Nothing to attach - either the repo had no previews for this domain, or every file
// was over the budget. The email still goes, describing the two directions in text.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _attachment_props: '', _attached: [] })
}));

// PREVIEW mode: TEST_RUN is on and TEST_EMAIL is blank, so nothing goes out.
// The full subject, html and text are still on the item - open this node's output in
// the execution view to read the exact email that would have been sent.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _outcome: 'preview', _would_send_to: i.json.email })
}));

// The SMTP node replaces the item with its own send result, so re-attach the lead.
// "send this one?" is the last node the full lead passed through untouched.
const cfg = $('config').first().json;
const lead = $('send this one?').first().json;
const result = $input.first().json || {};

return [{
  json: Object.assign({}, lead, {
    _outcome: cfg.test_send ? 'test_send' : 'sent',
    _sent_to: cfg.test_send ? cfg.test_email : lead.email,
    _message_id: result.messageId || '',
    _accepted: Array.isArray(result.accepted) ? result.accepted.length : null,
    _rejected: Array.isArray(result.rejected) ? result.rejected.length : null
  })
}];

// One row's worth of write-back, for both outcomes: sent, or no deliverables in the
// repo. Columns we are not deliberately changing are written back with the value we
// read, so a partial mapping can never blank a cell.
const cfg = $('config').first().json;
const C = cfg.columns;
const j = $input.first().json;

// 'preview' and 'test' compute exactly what a live run would write, so the operator can read
// it in the execution view. It is the 'write back?' gate that stops it reaching the sheet.
const sent = j._outcome === 'sent' || j._outcome === 'preview' || j._outcome === 'test_send';
const stamp = new Date().toISOString().slice(0, 10);

const noteLine = j._outcome === 'sent'
  ? stamp + ': deliverables emailed to ' + j.email
  : j._outcome === 'test_send'
  ? stamp + ': TEST - sent to ' + (j._sent_to || '') + ' instead of ' + j.email
  : j._outcome === 'preview'
  ? stamp + ': PREVIEW - would have emailed ' + j.email
  : stamp + ': skipped - ' + (j._skip_reason || 'no deliverables in repo');

const notes = [j.existing_notes, noteLine].filter(Boolean).join(' | ').slice(0, 900);

// A blank target in config means "leave that column exactly as it was".
const settle = (target, current) => (target ? target : current);

const row = {};
row[C.row_id]        = j.row_id;
row[C.task_progress] = sent
  ? settle(cfg.task_progress_after_send, j.task_progress)
  : settle(cfg.task_progress_no_deliverables, j.task_progress);
row[C.status]        = sent
  ? settle(cfg.status_after_send, j.status)
  : settle(cfg.status_no_deliverables, j.status);
row[C.next_action] = sent
  ? 'Follow up in 3 days if no reply'
  : 'Build deliverables for ' + j.domain + ' and push to ' + cfg.github_branch;
row[C.email_title]   = sent ? j.subject : (j.existing_title || '');
row[C.email_content] = sent ? j.text : (j.existing_body || '');
row[C.notes]         = notes;

return [{
  json: Object.assign({}, row, {
    _outcome: j._outcome,
    _row_id: j.row_id,
    _business: j.business,
    _email: j.email,
    _domain: j.domain,
    _subject: sent ? j.subject : '',
    _sent_to: j._sent_to || '',
    _copy_source: j._copy_source || '',
    _skip_reason: j._skip_reason || ''
  })
}];

// The Sheets node replaces the item with its own write result, so without this the
// run summary would have nothing left to name a row by. Re-attach the record and
// hand a small item back to the loop.
const cfg = $('config').first().json;
const rec = $('prepare sheet update').first().json;

return [{
  json: {
    _outcome:     rec._outcome,
    _row_id:      rec._row_id,
    _business:    rec._business,
    _email:       rec._email,
    _domain:      rec._domain,
    _subject:     rec._subject,
    _sent_to:     rec._sent_to,
    _copy_source: rec._copy_source,
    _skip_reason: rec._skip_reason,
    _written:     cfg.live_send === true
  }
}];

// The loop's done output carries every item that went back into it, so this is the
// only place with a whole-run view. Counts first, then the per-row detail.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json);

const selection = (() => {
  try { return $('pick sendable rows').first().json._summary || {}; } catch (e) { return {}; }
})();

const sent = items.filter((i) => i._outcome === 'sent');
const tested = items.filter((i) => i._outcome === 'test_send');
const previewed = items.filter((i) => i._outcome === 'preview');
const missing = items.filter((i) => i._outcome === 'no_deliverables');

const lines = [];
lines.push('Acme outreach - ' + new Date().toISOString().slice(0, 16).replace('T', ' '));
lines.push(
  cfg.mode === 'live' ? 'MODE: LIVE - real recipients, and the sheet is written'
  : cfg.mode === 'test' ? 'MODE: TEST RUN - every email redirected to ' + cfg.test_email + ', sheet untouched'
  : 'MODE: PREVIEW - nothing sent, nothing written. Set TEST_EMAIL to actually send.');
lines.push('');
lines.push('Rows read: ' + (selection.rows_read ?? '?') +
           '  eligible: ' + (selection.eligible ?? '?') +
           '  picked: ' + (selection.selected ?? items.length) +
           (selection.cap ? '  (cap ' + selection.cap + ' - ' + selection.cap_reason + ')' : ''));
lines.push('Sent: ' + sent.length + '   Test-sent: ' + tested.length +
           '   Previewed: ' + previewed.length + '   No deliverables: ' + missing.length);

if (selection.skipped) {
  const skips = Object.entries(selection.skipped).filter(([, n]) => n > 0);
  if (skips.length) {
    lines.push('');
    lines.push('Not picked:');
    for (const [reason, n] of skips) lines.push('  ' + reason.replace(/_/g, ' ') + ': ' + n);
  }
}

if (sent.length) {
  lines.push('');
  lines.push('Emailed:');
  for (const s of sent) lines.push('  #' + s._row_id + ' ' + s._business + ' <' + s._email + '>');
}
if (tested.length) {
  lines.push('');
  lines.push('Test-sent to ' + cfg.test_email + ', meant for:');
  for (const s2 of tested) lines.push('  #' + s2._row_id + ' ' + s2._business + ' <' + s2._email + '>');
}
if (previewed.length) {
  lines.push('');
  lines.push('Would have emailed:');
  for (const s of previewed) lines.push('  #' + s._row_id + ' ' + s._business + ' <' + s._email + '>');
}
if (missing.length) {
  lines.push('');
  lines.push('Nothing in the repo for:');
  for (const s of missing) lines.push('  #' + s._row_id + ' ' + s._domain + ' - ' + s._skip_reason);
}

return [{
  json: {
    text: lines.join('\n'),
    mode: cfg.mode,
    counts: { sent: sent.length, test_send: tested.length, preview: previewed.length,
              no_deliverables: missing.length },
    selection
  }
}];
